web-api.sail-expression:
a!localVariables(
  local!employeeId: http!request.queryParameters.employeeId,
  local!employee: rule!APN_getEmployeeById(employeeId: local!employeeId),
  a!httpResponse(
    statusCode: 200,
    headers: {
      a!httpHeader(name: "Content-Type", value: "application/json")
    },
    body: a!toJson(local!employee)
  )
)
